"use client";
import { useEffect, useState } from "react";

export default function Intro() {
  const [phase, setPhase] = useState(0); // 0 hidden, 1 text visible, 2 sliding away, 3 done

  useEffect(() => {
    const t1 = setTimeout(() => setPhase(1), 100);
    const t2 = setTimeout(() => setPhase(2), 2200);
    const t3 = setTimeout(() => setPhase(3), 3200);
    return () => {
      clearTimeout(t1);
      clearTimeout(t2);
      clearTimeout(t3);
    };
  }, []);

  if (phase === 3) return null;

  return (
    <div
      className={`fixed inset-0 z-[100] flex items-center justify-center bg-black transition-transform duration-1000 ease-in-out ${
        phase === 2 ? "-translate-y-full" : "translate-y-0"
      }`}
    >
      <h1
        className={`text-center text-3xl font-bold text-cyan-400 transition-all duration-1000 md:text-5xl ${
          phase >= 1 ? "translate-y-0 opacity-100" : "translate-y-10 opacity-0"
        }`}
      >
        Welcome to Aakriti Bastola Portfolio
      </h1>
    </div>
  );
}